const SESSION_KEY='pure-account-session-v1';
export function normalizeNickname(value){const n=String(value).normalize('NFKC').trim();if(!/^[A-Za-z0-9_\u4e00-\u9fff]{2,20}$/.test(n))throw Error('昵称须为2—20个中文、英文字母、数字或下划线');return n;}
export async function nicknameIdentity(value){const n=normalizeNickname(value).toLowerCase(),hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(n));return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')+'@accounts.example.com';}
export class CloudAccount extends EventTarget{
 constructor(){super();this.enabled=false;this.session=null;this.profile=null;this.records=new Map();this.paper={value:null,version:0};this.status='local';this.queue=Promise.resolve();this.refreshing=null;this.loading=null;this.ready=this.init();}
 emit(name,detail={}){this.dispatchEvent(new CustomEvent(name,{detail}));}
 setStatus(value,message=''){this.status=value;this.emit('status',{value,message});}
 get user(){return this.profile;}
 get device(){return innerWidth<650?'mobile':innerWidth<1000?'tablet':'desktop';}
 readSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY));}catch{return null;}}
 storeSession(data){if(!data.access_token||!data.refresh_token)throw Error('登录服务未返回有效会话，请确认已关闭此昵称账户项目的邮件确认');this.session={access_token:data.access_token,refresh_token:data.refresh_token,expires_at:data.expires_at||Math.floor(Date.now()/1000)+(data.expires_in||3600),user_id:data.user?.id||this.session?.user_id};try{localStorage.setItem(SESSION_KEY,JSON.stringify(this.session));}catch{throw Error('浏览器未允许保存登录会话，请启用网站存储后重试');}}
 clearSession(){this.session=null;this.profile=null;this.records.clear();this.paper={value:null,version:0};try{localStorage.removeItem(SESSION_KEY);}catch{}this.setStatus('signed-out');this.emit('logout');}
 async init(){try{const r=await fetch('account-config.json',{cache:'no-store'});if(!r.ok)throw Error('账户配置暂不可用');const c=await r.json();if(!c.enabled)return;const url=new URL(c.supabaseUrl);if(url.protocol!=='https:')throw Error('账户服务必须使用HTTPS');if(!c.publishableKey||c.publishableKey.startsWith('sb_secret_'))throw Error('账户服务须配置公共publishable或anon密钥');if(c.publishableKey.split('.').length===3){try{const payload=JSON.parse(atob(c.publishableKey.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role!=='anon')throw Error('请勿配置服务端私密密钥');}catch(e){throw Error('账户公共密钥格式不正确');}}this.config={url:url.origin,key:c.publishableKey};this.enabled=true;this.session=this.readSession();if(this.session?.refresh_token){try{await this.load();}catch(e){if(e.status===401)this.clearSession();else{this.setStatus('error',e.message);throw e;}}}else this.setStatus('signed-out');
 window.addEventListener('storage',e=>{if(e.key!==SESSION_KEY)return;const next=this.readSession();if(!next||next.user_id!==this.session?.user_id){this.session=next;this.profile=null;this.records.clear();this.emit('account-switch');}else this.session=next;});
 window.addEventListener('online',()=>{if(this.session)this.reload().catch(e=>this.setStatus('error',e.message));});
 window.addEventListener('focus',()=>{if(this.session&&document.visibilityState==='visible')this.reload().catch(e=>this.setStatus('error',e.message));});
 this.heartbeat=setInterval(()=>{if(this.user&&document.visibilityState==='visible')this.activity('heartbeat',this.pageName()).catch(()=>{});},60000);
 }catch(e){this.error=e;this.setStatus('error',e.message);}}
 async request(path,{method='POST',body,authenticated=false,retried=false}={}){if(!this.enabled)throw Error('云端账户尚未启用');if(authenticated)await this.ensureToken();const headers={apikey:this.config.key,'Content-Type':'application/json'};if(authenticated)headers.Authorization='Bearer '+this.session.access_token;let r;try{r=await fetch(this.config.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(20000)});}catch{const e=Error('网络连接失败，本次更改未确认同步，请稍后重试');e.network=true;throw e;}let value;try{value=await r.json();}catch{value=null;}if(r.status===401&&authenticated&&!retried){await this.refresh();return this.request(path,{method,body,authenticated,retried:true});}if(!r.ok){const e=Error(this.message(r.status,value));e.status=r.status;throw e;}return value;}
 message(status,value){if(status===409)return'另一设备已修改记录，已重新读取云端，请重试本次操作';if(status===401)return'登录已失效或昵称、密码不正确，请重新登录';if(status===403)return'没有访问权限';if(status===429)return'操作过于频繁，请稍后重试';if(value?.code==='invalid_credentials'||value?.error_code==='invalid_credentials')return'昵称或密码不正确';if(value?.code==='weak_password'||value?.error_code==='weak_password')return'密码强度不足，请使用更长的密码';if(value?.code==='user_already_exists')return'该昵称已被注册';if(value?.msg?.includes('Database error')||value?.message?.includes('Database error'))return'昵称已被使用，或账户服务尚未配置完成';if(value?.code?.startsWith('PT')&&value.message)return value.message;return'账户服务请求失败，请稍后重试或联系管理员';}
 async ensureToken(){if(!this.session?.refresh_token){const e=Error('请先登录');e.status=401;throw e;}if(this.session.expires_at*1000<Date.now()+60000)await this.refresh();}
 async refresh(){if(this.refreshing)return this.refreshing;this.refreshing=(async()=>{const old=this.session?.refresh_token;if(!old){const e=Error('请先登录');e.status=401;throw e;}const run=async()=>{const latest=this.readSession();if(latest&&latest.refresh_token!==old){this.session=latest;return;}const data=await this.request('/auth/v1/token?grant_type=refresh_token',{body:{refresh_token:old}});this.storeSession(data);};try{if(navigator.locks)await navigator.locks.request('pure-account-refresh',run);else await run();}catch(e){if(e.status===400||e.status===401){this.clearSession();e.status=401;}throw e;}})().finally(()=>this.refreshing=null);return this.refreshing;}
 async rpc(name,body={}){return this.request('/rest/v1/rpc/'+name,{body,authenticated:true});}
 async load(){if(this.loading)return this.loading;this.loading=(async()=>{const v=await this.rpc('pp_snapshot');if(!v?.profile||!Array.isArray(v.records))throw Error('账户数据格式不正确');this.profile=v.profile;this.records=new Map(v.records.map(r=>[r.question_id,r]));this.paper=v.paper||{value:null,version:0};this.setStatus('synced');return v;})().finally(()=>this.loading=null);return this.loading;}
 async reload(){await this.queue.catch(()=>{});const before=JSON.stringify({records:[...this.records],paper:this.paper});await this.load();if(before!==JSON.stringify({records:[...this.records],paper:this.paper}))this.emit('records',{external:true});}
 async requireUser(){await this.ready;if(this.error)throw this.error;if(this.enabled&&!this.user){const next=location.pathname.split('/').pop()+location.search+location.hash;location.replace('account.html?next='+encodeURIComponent(next));throw Error('请先登录');}}
 async signup(nickname,password){await this.ready;if(!this.enabled)throw Error('云端账户尚未启用');const nick=normalizeNickname(nickname);if([...password].length<12||new TextEncoder().encode(password).length>72)throw Error('密码至少12个字符；如提示过长，请减少字符');const email=await nicknameIdentity(nick);const v=await this.request('/auth/v1/signup',{body:{email,password,data:{nickname:nick}}});this.storeSession(v);await this.load();this.emit('login');}
 async signin(nickname,password){await this.ready;const email=await nicknameIdentity(nickname),v=await this.request('/auth/v1/token?grant_type=password',{body:{email,password}});this.storeSession(v);await this.load();this.emit('login');}
 async signout(){await this.queue.catch(()=>{});try{if(this.session)await this.request('/auth/v1/logout?scope=local',{authenticated:true,body:{}});}finally{this.clearSession();}}
 async changePassword(current,password){if([...password].length<12||new TextEncoder().encode(password).length>72)throw Error('新密码至少12个字符；如提示过长，请减少字符');const email=await nicknameIdentity(this.user.nickname);const v=await this.request('/auth/v1/token?grant_type=password',{body:{email,password:current}});this.storeSession(v);await this.request('/auth/v1/user',{method:'PUT',authenticated:true,body:{password,current_password:current}});}
 getState(kind){const rows=[...this.records.values()].filter(r=>kind==='original'?r.question_id.includes('-C'):!r.question_id.includes('-C'));return{version:1,saved:rows.filter(r=>r.saved).map(r=>r.question_id),done:rows.filter(r=>r.done).map(r=>r.question_id)};}
 commitState(kind,next){const desired={saved:new Set(next.saved),done:new Set(next.done)};const run=async()=>{if(!this.user)throw Error('请先登录');this.setStatus('syncing');const current=this.getState(kind),all=new Set([...current.saved,...current.done,...desired.saved,...desired.done]),changes=[];for(const id of all){const old=this.records.get(id)||{saved:false,done:false,version:0},saved=desired.saved.has(id),done=desired.done.has(id);if(saved!==old.saved||done!==old.done){const row={question_id:id,base_version:old.version};if(saved!==old.saved)row.saved=saved;if(done!==old.done)row.done=done;changes.push(row);}}if(!changes.length){this.setStatus('synced');return;}try{const updated=await this.rpc('pp_apply_records',{p_changes:changes});for(const r of updated)this.records.set(r.question_id,r);this.setStatus('synced');}catch(e){if(e.status===409)await this.load();this.setStatus('error',e.message);throw e;}};const promise=this.queue.then(run);this.queue=promise.catch(()=>{});return promise;}
 setPaper(value){const run=async()=>{this.setStatus('syncing');try{this.paper=await this.rpc('pp_save_paper',{p_paper:value,p_base_version:this.paper.version});this.setStatus('synced');}catch(e){if(e.status===409)await this.load();this.setStatus('error',e.message);throw e;}};const p=this.queue.then(run);this.queue=p.catch(()=>{});return p;}
 pageName(){return location.pathname.endsWith('past.html')?'past':location.pathname.endsWith('admin.html')?'admin':location.pathname.endsWith('account.html')?'account':(['saved','papers','books'].includes(location.hash.slice(1))?location.hash.slice(1):'original');}
 async activity(kind,page=this.pageName(),id=null){if(!this.enabled||!this.user)return;await this.rpc('pp_activity_ping',{p_kind:kind,p_page:page,p_question_id:id,p_device:this.device});}
 async adminUsers(search='',offset=0){return this.rpc('pp_admin_users',{p_search:search,p_offset:offset,p_limit:30});}
 async adminActivity(id){return this.rpc('pp_admin_activity',{p_user_id:id});}
}
export const account=new CloudAccount();
export async function mountAccountLink(){await account.ready;const header=document.querySelector('.topbar');if(!header)return;let a=document.querySelector('#cloud-account-link');if(!a){a=document.createElement('a');a.id='cloud-account-link';a.className='account-link';a.href='account.html';header.append(a);}const render=()=>{const labels={local:'本机模式','signed-out':'登录 / 注册',syncing:'正在同步',synced:'云端已同步',error:'同步待确认'};a.textContent=account.user?account.user.nickname+' · '+labels[account.status]:(account.enabled?'登录 / 注册':'账户（待启用）');a.title=account.enabled?'个人账户与云端记录':'云端账户尚未启用';document.body.classList.toggle('cloud-enabled',account.enabled);};render();account.addEventListener('status',render);account.addEventListener('account-switch',()=>location.replace('account.html'));account.addEventListener('logout',()=>{if(!location.pathname.endsWith('account.html'))location.replace('account.html');});}
